export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-21\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 21,\n    \"title\": \"難四\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 10,\n    \"passageIds\": [\n      \"han-fei-zi_ch-21_p-1\",\n      \"han-fei-zi_ch-21_p-2\",\n      \"han-fei-zi_ch-21_p-3\",\n      \"han-fei-zi_ch-21_p-4\",\n      \"han-fei-zi_ch-21_p-5\",\n      \"han-fei-zi_ch-21_p-6\",\n      \"han-fei-zi_ch-21_p-7\",\n      \"han-fei-zi_ch-21_p-8\",\n      \"han-fei-zi_ch-21_p-9\",\n      \"han-fei-zi_ch-21_p-10\",\n      \"han-fei-zi_ch-21_p-11\",\n      \"han-fei-zi_ch-21_p-12\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 1,\n      \"canonicalText\": \"衛孫文子聘於魯，公登亦登。叔孫穆子趨進曰：「諸侯之會，寡君未嘗後衛君也。今子不後寡君一等，寡君未知所過也，子其少安。」孫子無辭，亦無悛容。穆子退而告人曰：「孫子必亡。亡臣而不後君，過而不悛，亡之本也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-1_s-1\",\n        \"han-fei-zi_ch-21_p-1_s-2\",\n        \"han-fei-zi_ch-21_p-1_s-3\",\n        \"han-fei-zi_ch-21_p-1_s-4\",\n        \"han-fei-zi_ch-21_p-1_s-5\",\n        \"han-fei-zi_ch-21_p-1_s-6\",\n        \"han-fei-zi_ch-21_p-1_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"衛孫文子聘於魯，公登亦登。叔孫穆子趨進說道：諸侯的會，寡國君未嘗後衛國君啊。今子不後寡國君一等，寡國君未知所過啊，子他的少安。孫子無辭，亦無悛容。穆子退而且告人說道：孫子必亡。亡臣屬而且不後國君，過而且不悛，亡的本啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「衛孫文子聘於魯，公登亦登」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「衛」、「孫」、「文」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「衛孫文子聘於魯公登亦登叔孫穆子趨進曰諸侯之會寡君」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「叔孫穆子趨進曰：「諸侯之會，寡君未嘗後衛君也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 2,\n      \"canonicalText\": \"或曰：天子失道，諸侯伐之，故有湯、武。諸侯失道，大夫伐之，故有齊、晉。臣而伐君者必亡，則是湯、武不王，晉、齊不立也。孫子君於衛，而後不臣於魯，臣之君也。君有失也，故臣有得也。不命亡於有失之君，而命亡於有得之臣，不察。魯不得誅衛大夫，而衛君之明不知不悛之臣，孫子雖有是二也臣以亡？其所以亡其失所以得君也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-2_s-1\",\n        \"han-fei-zi_ch-21_p-2_s-2\",\n        \"han-fei-zi_ch-21_p-2_s-3\",\n        \"han-fei-zi_ch-21_p-2_s-4\",\n        \"han-fei-zi_ch-21_p-2_s-5\",\n        \"han-fei-zi_ch-21_p-2_s-6\",\n        \"han-fei-zi_ch-21_p-2_s-7\",\n        \"han-fei-zi_ch-21_p-2_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：天子失道，諸侯伐的，所以有湯、武。諸侯失道，大夫伐的，所以有齊、晉。臣屬而且伐國君的人或事必亡，則是湯、武不王，晉、齊不立啊。孫子國君於衛，而且後不臣屬於魯，臣屬的國君啊。國君有失啊，所以臣屬有得啊。不命亡於有失的國君，而且命亡於有得的臣屬，不察。魯不得誅衛大夫，而且衛國君的明不知不悛的臣屬，孫子雖有是二啊臣屬以亡？他的所以亡他的失所以得國君啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：天子失道，諸侯伐之，故有湯、武」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「天」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰天子失道諸侯伐之故有湯武諸侯失道大夫伐之故有」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「諸侯失道，大夫伐之，故有齊、晉」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 3,\n      \"canonicalText\": \"或曰：臣主之施分也。臣能奪君者，以得相踦也。故非其分而取者，眾之所奪也；辭其分而取者，民之所予也。是以桀索崏山之女，紂求比干之心，而天下離；湯身易名，武身受詈，而海內服；趙咺走山，田外僕，而齊、晉從。則湯、武之所以王，齊、晉之所以立，非必以其君也，彼得之而後以君處之也。今未有其所以得，而行其所以處，是倒義而逆德也。倒義，則事之所以敗也，逆德，則怨之所以聚也；敗亡之不察何也！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-3_s-1\",\n        \"han-fei-zi_ch-21_p-3_s-2\",\n        \"han-fei-zi_ch-21_p-3_s-3\",\n        \"han-fei-zi_ch-21_p-3_s-4\",\n        \"han-fei-zi_ch-21_p-3_s-5\",\n        \"han-fei-zi_ch-21_p-3_s-6\",\n        \"han-fei-zi_ch-21_p-3_s-7\",\n        \"han-fei-zi_ch-21_p-3_s-8\",\n        \"han-fei-zi_ch-21_p-3_s-9\",\n        \"han-fei-zi_ch-21_p-3_s-10\",\n        \"han-fei-zi_ch-21_p-3_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：臣屬主的施分啊。臣屬能奪國君的人或事，以得相踦啊。所以絕不是他的分而且取的人或事，眾的所奪啊；辭他的分而且取的人或事，民的所予啊。是以桀索崏山的女，紂求比干的心，而且天下離；湯身易名，武身受詈，而且海內服；趙咺走山，田外僕，而且齊、晉從。則湯、武的所以王，齊、晉的所以立，絕不是必以他的國君啊，彼得的而且後以國君處的啊。今未有他的所以得，而且行他的所以處，是倒義而且逆德啊。倒義，則事的所以敗啊，逆德，則怨的所以聚啊；敗亡的不察何啊！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：臣主之施分也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「臣」、「主」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰臣主之施分也臣能奪君者以得相踦也故非其分而取」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「臣能奪君者，以得相踦也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 4,\n      \"canonicalText\": \"魯陽虎欲攻三桓，不剋而奔齊，景公禮之。鮑文子諫曰：「不可。陽虎有寵於季氏而欲伐於季孫，貪其富也。今君富於季孫，而齊大於魯，陽虎所以盡詐也。」景公乃囚陽虎。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-4_s-1\",\n        \"han-fei-zi_ch-21_p-4_s-2\",\n        \"han-fei-zi_ch-21_p-4_s-3\",\n        \"han-fei-zi_ch-21_p-4_s-4\",\n        \"han-fei-zi_ch-21_p-4_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"魯陽虎欲攻三桓，不剋而且奔齊，景公禮的。鮑文子諫說道：不可。陽虎有寵於季氏而且欲伐於季孫，貪他的富啊。今君主統治者富於季孫，而且齊大於魯，陽虎所以盡詐啊。景公乃囚陽虎。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「魯陽虎欲攻三桓，不剋而奔齊，景公禮之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「魯」、「陽」、「虎」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「魯陽虎欲攻三桓不剋而奔齊景公禮之鮑文子諫曰不可陽」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「鮑文子諫曰：「不可」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 5,\n      \"canonicalText\": \"或曰：千金之家，其子不仁，人之急利甚也。桓公，五伯之上也，爭國而殺其兄，其利大也。臣主之間，非兄弟之親也。劫殺之功，制萬乘而享大利，則群臣孰非陽虎也。事以微巧成，以疏拙敗。群臣之未起難也，其備未具也。群臣皆有陽虎之心，而君上不知，是微而巧也。陽虎貪，於天下，以欲攻上，是疏而拙也。不使景公加誅於拙虎，是鮑文子之說反也。臣之忠詐，在君所行也。君明而嚴則群臣忠，君懦而闇則群臣詐。知微之謂明，無赦之謂嚴。不知齊之巧臣而誅魯之成亂，不亦妄乎！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-5_s-1\",\n        \"han-fei-zi_ch-21_p-5_s-2\",\n        \"han-fei-zi_ch-21_p-5_s-3\",\n        \"han-fei-zi_ch-21_p-5_s-4\",\n        \"han-fei-zi_ch-21_p-5_s-5\",\n        \"han-fei-zi_ch-21_p-5_s-6\",\n        \"han-fei-zi_ch-21_p-5_s-7\",\n        \"han-fei-zi_ch-21_p-5_s-8\",\n        \"han-fei-zi_ch-21_p-5_s-9\",\n        \"han-fei-zi_ch-21_p-5_s-10\",\n        \"han-fei-zi_ch-21_p-5_s-11\",\n        \"han-fei-zi_ch-21_p-5_s-12\",\n        \"han-fei-zi_ch-21_p-5_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：千金的家，他的子不仁，人的急利甚啊。桓公，五伯的上啊，爭國而且殺他的兄，他的利大啊。臣屬主的間，絕不是兄弟的親啊。劫殺的功，制萬乘而且享大利，則群臣屬孰絕不是陽虎啊。事以微巧成，以疏拙敗。群臣屬的未起難啊，他的備未具啊。群臣屬皆有陽虎的心，而且國君上不知，是微而且巧啊。陽虎貪，於天下，以欲攻上，是疏而且拙啊。不使景公加誅於拙虎，是鮑文子的說反啊。臣屬的忠詐，在國君所行啊。國君明而且嚴則群臣屬忠，國君懦而且闇則群臣屬詐。知微的謂明，無赦的謂嚴。不知齊的巧臣屬而且誅魯的成亂，不亦妄乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：千金之家，其子不仁，人之急利甚也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「千」、「金」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰千金之家其子不仁人之急利甚也桓公五伯之上也爭」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「桓公，五伯之上也，爭國而殺其兄，其利大也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 6,\n      \"canonicalText\": \"或曰：仁貪不同心。故公子目夷辭宋，而楚商臣弒父，鄭去疾予弟，而魯桓弒兄，五伯兼併，而以桓律人；則是皆無貞廉也。且君明而嚴則群臣忠，陽虎為亂於魯，不成而走，入齊而不誅，是承為亂也。君明則誅，知陽虎之可以濟亂也，此見微之情也。語曰：「諸侯以國為親。」君嚴則陽虎之罪不可失，此無赦之實也。則誅陽虎，所以使群臣忠也。未知齊之巧臣，而廢明亂之罰；責以未然，而不誅昭昭之罪；此則妄矣。今誅魯之罪亂以威群臣之有姦心者，而可以得季、孟、叔孫之親，鮑文之說，何以為反？\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-6_s-1\",\n        \"han-fei-zi_ch-21_p-6_s-2\",\n        \"han-fei-zi_ch-21_p-6_s-3\",\n        \"han-fei-zi_ch-21_p-6_s-4\",\n        \"han-fei-zi_ch-21_p-6_s-5\",\n        \"han-fei-zi_ch-21_p-6_s-6\",\n        \"han-fei-zi_ch-21_p-6_s-7\",\n        \"han-fei-zi_ch-21_p-6_s-8\",\n        \"han-fei-zi_ch-21_p-6_s-9\",\n        \"han-fei-zi_ch-21_p-6_s-10\",\n        \"han-fei-zi_ch-21_p-6_s-11\",\n        \"han-fei-zi_ch-21_p-6_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：仁貪不同心。所以公子目夷辭宋，而且楚商臣屬弒父，鄭去疾予弟，而且魯桓弒兄，五伯兼併，而且以桓律人；則是皆無貞廉啊。且國君明而且嚴則群臣屬忠，陽虎為亂於魯，不成而且走，入齊而且不誅，是承為亂啊。國君明則誅，知陽虎的可以濟亂啊，此見微的情啊。語說道：諸侯以國為親。國君嚴則陽虎的罪不可失，此無赦的實啊。則誅陽虎，所以使群臣屬忠啊。未知齊的巧臣屬，而且廢明亂的刑罰；責以未然，而且不誅昭昭的罪；此則妄矣。今誅魯的罪亂以威群臣屬的有姦心的人或事，而且可以得季、孟、叔孫的親，鮑文的說，何以為反？\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：仁貪不同心」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「仁」、「貪」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰仁貪不同心故公子目夷辭宋而楚商臣弒父鄭去疾予」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「故公子目夷辭宋，而楚商臣弒父，鄭去疾予弟，而魯桓弒兄，五伯兼併，而以桓律人」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 7,\n      \"canonicalText\": \"鄭伯將以高渠彌為卿，昭公惡之，固諫不聽。及昭公即位，懼其殺己也，辛卯，弒昭公而立子亶也。君子曰：「昭公知所惡矣。」公子圉曰：「高伯其為戮乎，報惡已甚矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-7_s-1\",\n        \"han-fei-zi_ch-21_p-7_s-2\",\n        \"han-fei-zi_ch-21_p-7_s-3\",\n        \"han-fei-zi_ch-21_p-7_s-4\",\n        \"han-fei-zi_ch-21_p-7_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"鄭伯將以高渠彌為卿，昭公惡的，固諫不聽。及昭公即位，懼他的殺己啊，辛卯，弒昭公而且立子亶啊。君主統治者子說道：昭公知所惡矣。公子圉說道：高伯他的為戮乎，報惡已甚矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「鄭伯將以高渠彌為卿，昭公惡之，固諫不聽」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「鄭」、「伯」、「將」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「鄭伯將以高渠彌為卿昭公惡之固諫不聽及昭公即位懼其」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「及昭公即位，懼其殺己也，辛卯，弒昭公而立子亶也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 8,\n      \"canonicalText\": \"或曰：公子圉之言也不亦反乎！昭公之及於難者，報惡晚也。然則高伯之晚於死者，報惡甚也。明君不懸怒，懸怒則臣罪輕舉以行計，則人主危。故靈臺之飲，衛侯怒而不誅，故褚師作難；食黿之羹，鄭君怒而不誅，故子公殺君。君子之舉知所惡，非甚之也，曰知之若是其明也，而不行誅焉，以及於死，故知所惡，以見其無權也。人君非獨不足於見難而已，或不足於斷制。今昭公見惡稽罪而不誅，使渠彌含憎懼死以徼倖，故不免於殺，是昭公之報惡不甚也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-8_s-1\",\n        \"han-fei-zi_ch-21_p-8_s-2\",\n        \"han-fei-zi_ch-21_p-8_s-3\",\n        \"han-fei-zi_ch-21_p-8_s-4\",\n        \"han-fei-zi_ch-21_p-8_s-5\",\n        \"han-fei-zi_ch-21_p-8_s-6\",\n        \"han-fei-zi_ch-21_p-8_s-7\",\n        \"han-fei-zi_ch-21_p-8_s-8\",\n        \"han-fei-zi_ch-21_p-8_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：公子圉的言啊不亦反乎！昭公的及於難的人或事，報惡晚啊。然則高伯的晚於死的人或事，報惡甚啊。明國君不懸怒，懸怒則臣屬罪輕舉以行計，則人主危。所以靈臺的飲，衛侯怒而且不誅，所以褚師作難；食黿的羹，鄭國君怒而且不誅，所以子公殺國君。國君子的舉知所惡，絕不是甚的啊，說道：知的若是他的明啊，而且不行誅焉，以及於死，所以知所惡，以見他的無權啊。人國君絕不是獨不足於見難而且已，或不足於斷制。今昭公見惡稽罪而且不誅，使渠彌含憎懼死以徼倖，所以不免於殺，是昭公的報惡不甚啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：公子圉之言也不亦反乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「公」、「子」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰公子圉之言也不亦反乎昭公之及於難者報惡晚也然」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「昭公之及於難者，報惡晚也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 9,\n      \"canonicalText\": \"或曰：報惡甚者，大誅報小罪。大誅報小罪也者，獄之至也。獄之患，故非在所以誅也，以讎之眾也。是以晉厲公滅三郤而欒中行作難，鄭子都殺伯咺而食鼎起禍，吳王誅子胥而越句踐成霸。則衛侯之逐，鄭靈之弒，不以褚師之不死而子公之不誅也，以未可以怒而有怒之色，未可誅而有誅之心。怒其當罪，而誅不逆人心，雖懸奚害？夫未立有罪，即位之後，宿罪而誅，齊胡之所以滅也。君行之臣，猶有後患，況為臣而行之君乎？誅既不當，而以盡為心，是與天下為讎也，則雖為戮，不亦可乎！\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-9_s-1\",\n        \"han-fei-zi_ch-21_p-9_s-2\",\n        \"han-fei-zi_ch-21_p-9_s-3\",\n        \"han-fei-zi_ch-21_p-9_s-4\",\n        \"han-fei-zi_ch-21_p-9_s-5\",\n        \"han-fei-zi_ch-21_p-9_s-6\",\n        \"han-fei-zi_ch-21_p-9_s-7\",\n        \"han-fei-zi_ch-21_p-9_s-8\",\n        \"han-fei-zi_ch-21_p-9_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：報惡甚的人或事，大誅報小罪。大誅報小罪啊的人或事，獄的至啊。獄的患，所以絕不是在所以誅啊，以讎的眾啊。是以晉厲公滅三郤而且欒中行作難，鄭子都殺伯咺而且食鼎起禍，吳王誅子胥而且越句踐成霸。則衛侯的逐，鄭靈的弒，不以褚師的不死而且子公的不誅啊，以未可以怒而且有怒的色，未可誅而且有誅的心。怒他的當罪，而且誅不逆人心，雖懸奚害？夫未立有罪，即位的後，宿罪而且誅，齊胡的所以滅啊。國君行的臣屬，猶有後患，況為臣屬而且行的國君乎？誅既不當，而且以盡為心，是與天下為讎啊，則雖為戮，不亦可乎！\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：報惡甚者，大誅報小罪」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「報」、「惡」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰報惡甚者大誅報小罪大誅報小罪也者獄之至也獄之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「大誅報小罪也者，獄之至也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 10,\n      \"canonicalText\": \"衛靈公之時，彌子瑕有寵，於衛國。侏儒有見公者曰：「臣之夢淺矣。」公曰：「奚夢？」「夢見竈者，為見公也。」公怒曰：「吾聞見人主者夢見日，奚為見寡人而夢見竈乎？」侏儒曰：「夫日兼照天下，一物不能當也。人君兼照一國，一人不能壅也，故將見人主而夢日也。夫竈，一人煬焉，則後人無從見矣。或者一人煬君邪？則臣雖夢竈，不亦可乎！」公曰：「善。」遂去雍鉏，退彌子瑕，而用司空狗。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-10_s-1\",\n        \"han-fei-zi_ch-21_p-10_s-2\",\n        \"han-fei-zi_ch-21_p-10_s-3\",\n        \"han-fei-zi_ch-21_p-10_s-4\",\n        \"han-fei-zi_ch-21_p-10_s-5\",\n        \"han-fei-zi_ch-21_p-10_s-6\",\n        \"han-fei-zi_ch-21_p-10_s-7\",\n        \"han-fei-zi_ch-21_p-10_s-8\",\n        \"han-fei-zi_ch-21_p-10_s-9\",\n        \"han-fei-zi_ch-21_p-10_s-10\",\n        \"han-fei-zi_ch-21_p-10_s-11\",\n        \"han-fei-zi_ch-21_p-10_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"衛靈公的時，彌子瑕有寵，於衛國。侏儒有見公的人或事說道：臣屬的夢淺矣。公說道：奚夢？夢見竈的人或事，為見公啊。公怒說道：吾聞見人主的人或事夢見日，奚為見寡人而且夢見竈乎？侏儒說道：夫日兼照天下，一物不能當啊。人國君兼照一國，一人不能壅啊，所以將見人主而且夢日啊。夫竈，一人煬焉，則後人無從見矣。或的人或事一人煬國君邪？則臣屬雖夢竈，不亦可乎！公說道：善。遂去雍鉏，退彌子瑕，而且用司空狗。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「衛靈公之時，彌子瑕有寵，於衛國」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「衛」、「靈」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「衛靈公之時彌子瑕有寵於衛國侏儒有見公者曰臣之夢淺」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「侏儒有見公者曰：「臣之夢淺矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 11,\n      \"canonicalText\": \"或曰：侏儒善假於夢以見主道矣，然靈公不知侏儒之言也。去雍鉏，退彌子瑕，而用司空狗者，是去所愛而用所賢也。鄭子都賢慶建而壅焉，燕子噲賢子之而壅焉，夫去所愛而用所賢，未免使一人煬己也。不肖者煬主不足以害明，今不加知而使賢者煬己，則必危矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-11_s-1\",\n        \"han-fei-zi_ch-21_p-11_s-2\",\n        \"han-fei-zi_ch-21_p-11_s-3\",\n        \"han-fei-zi_ch-21_p-11_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：侏儒善假於夢以見主道矣，然靈公不知侏儒的言啊。去雍鉏，退彌子瑕，而且用司空狗的人或事，是去所愛而且用所賢啊。鄭子都賢慶建而且壅焉，燕子噲賢子的而且壅焉，夫去所愛而且用所賢，未免使一人煬己啊。不肖的人或事煬主不足以害明，今不加知而且使賢的人或事煬己，則必危矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰：侏儒善假於夢以見主道矣，然靈公不知侏儒之言也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「侏」、「儒」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰侏儒善假於夢以見主道矣然靈公不知侏儒之言也去」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「去雍鉏，退彌子瑕，而用司空狗者，是去所愛而用所賢也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"order\": 12,\n      \"canonicalText\": \"或曰屈到嗜芰，文王嗜菖蒲葅，非正味也，而二賢尚之，所味不必美。晉靈侯說參無恤，燕噲賢子之，非正士也，而二君尊之，所賢不必賢也。非賢而賢用之，與愛而用之同。賢誠賢而舉之，與用所愛異狀。故楚莊舉叔孫而霸，商辛用費仲而滅，此皆用所賢而事相反也。燕噲雖舉所賢而同於用所愛，衛奚距然哉？則侏儒之未可見也。君壅而不知其壅也，已見之後而知其壅也，故退壅臣，是加知之也。日「不加知而使賢者煬己則必危」，而今以加知矣，則雖煬己必不危矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-21_p-12_s-1\",\n        \"han-fei-zi_ch-21_p-12_s-2\",\n        \"han-fei-zi_ch-21_p-12_s-3\",\n        \"han-fei-zi_ch-21_p-12_s-4\",\n        \"han-fei-zi_ch-21_p-12_s-5\",\n        \"han-fei-zi_ch-21_p-12_s-6\",\n        \"han-fei-zi_ch-21_p-12_s-7\",\n        \"han-fei-zi_ch-21_p-12_s-8\",\n        \"han-fei-zi_ch-21_p-12_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"或說道：屈到嗜芰，文王嗜菖蒲葅，絕不是正味啊，而且二賢尚的，所味不必美。晉靈侯說參無恤，燕噲賢子的，絕不是正士啊，而且二國君尊的，所賢不必賢啊。絕不是賢而且賢用的，與愛而且用的同。賢誠賢而且舉的，與用所愛異狀。所以楚莊舉叔孫而且霸，商辛用費仲而且滅，此皆用所賢而且事相反啊。燕噲雖舉所賢而且同於用所愛，衛奚距然哉？則侏儒的未可見啊。國君壅而且不知他的壅啊，已見的後而且知他的壅啊，所以退壅臣屬，是加知的啊。日不加知而且使賢的人或事煬己則必危，而且今以加知矣，則雖煬己必不危矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈難四〉。韓非深刻融合法、術、勢三大治國精要，此處「或曰屈到嗜芰，文王嗜菖蒲葅，非正味也，而二賢尚之，所味不必美」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「或」、「屈」、「到」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「或曰屈到嗜芰文王嗜菖蒲葅非正味也而二賢尚之所味不」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「晉靈侯說參無恤，燕噲賢子之，非正士也，而二君尊之，所賢不必賢也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"衛孫文子聘於魯，公登亦登。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"叔孫穆子趨進曰：「諸侯之會，寡君未嘗後衛君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"今子不後寡君一等，寡君未知所過也，子其少安。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"」孫子無辭，亦無悛容。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"穆子退而告人曰：「孫子必亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"亡臣而不後君，過而不悛，亡之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：天子失道，諸侯伐之，故有湯、武。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"諸侯失道，大夫伐之，故有齊、晉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"臣而伐君者必亡，則是湯、武不王，晉、齊不立也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"孫子君於衛，而後不臣於魯，臣之君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"君有失也，故臣有得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"不命亡於有失之君，而命亡於有得之臣，不察。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"魯不得誅衛大夫，而衛君之明不知不悛之臣，孫子雖有是二也臣以亡？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-2_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"其所以亡其失所以得君也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：臣主之施分也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"臣能奪君者，以得相踦也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"故非其分而取者，眾之所奪也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"辭其分而取者，民之所予也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"是以桀索崏山之女，紂求比干之心，而天下離；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"湯身易名，武身受詈，而海內服；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"趙咺走山，田外僕，而齊、晉從。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"則湯、武之所以王，齊、晉之所以立，非必以其君也，彼得之而後以君處之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"今未有其所以得，而行其所以處，是倒義而逆德也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"倒義，則事之所以敗也，逆德，則怨之所以聚也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-3_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"敗亡之不察何也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"魯陽虎欲攻三桓，不剋而奔齊，景公禮之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"鮑文子諫曰：「不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"陽虎有寵於季氏而欲伐於季孫，貪其富也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"今君富於季孫，而齊大於魯，陽虎所以盡詐也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"」景公乃囚陽虎。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：千金之家，其子不仁，人之急利甚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"桓公，五伯之上也，爭國而殺其兄，其利大也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"臣主之間，非兄弟之親也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"劫殺之功，制萬乘而享大利，則群臣孰非陽虎也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"事以微巧成，以疏拙敗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"群臣之未起難也，其備未具也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"群臣皆有陽虎之心，而君上不知，是微而巧也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"陽虎貪，於天下，以欲攻上，是疏而拙也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"不使景公加誅於拙虎，是鮑文子之說反也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"臣之忠詐，在君所行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"君明而嚴則群臣忠，君懦而闇則群臣詐。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"知微之謂明，無赦之謂嚴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-5_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"不知齊之巧臣而誅魯之成亂，不亦妄乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：仁貪不同心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"故公子目夷辭宋，而楚商臣弒父，鄭去疾予弟，而魯桓弒兄，五伯兼併，而以桓律人；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"則是皆無貞廉也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"且君明而嚴則群臣忠，陽虎為亂於魯，不成而走，入齊而不誅，是承為亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"君明則誅，知陽虎之可以濟亂也，此見微之情也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"語曰：「諸侯以國為親。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"」君嚴則陽虎之罪不可失，此無赦之實也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"則誅陽虎，所以使群臣忠也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"未知齊之巧臣，而廢明亂之罰；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"責以未然，而不誅昭昭之罪；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"此則妄矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"今誅魯之罪亂以威群臣之有姦心者，而可以得季、孟、叔孫之親，鮑文之說，何以為反？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"鄭伯將以高渠彌為卿，昭公惡之，固諫不聽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"及昭公即位，懼其殺己也，辛卯，弒昭公而立子亶也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"君子曰：「昭公知所惡矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"」公子圉曰：「高伯其為戮乎，報惡已甚矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：公子圉之言也不亦反乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"昭公之及於難者，報惡晚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"然則高伯之晚於死者，報惡甚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"明君不懸怒，懸怒則臣罪輕舉以行計，則人主危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"故靈臺之飲，衛侯怒而不誅，故褚師作難；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"食黿之羹，鄭君怒而不誅，故子公殺君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"君子之舉知所惡，非甚之也，曰知之若是其明也，而不行誅焉，以及於死，故知所惡，以見其無權也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"人君非獨不足於見難而已，或不足於斷制。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"今昭公見惡稽罪而不誅，使渠彌含憎懼死以徼倖，故不免於殺，是昭公之報惡不甚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：報惡甚者，大誅報小罪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"大誅報小罪也者，獄之至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"獄之患，故非在所以誅也，以讎之眾也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"是以晉厲公滅三郤而欒中行作難，鄭子都殺伯咺而食鼎起禍，吳王誅子胥而越句踐成霸。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"則衛侯之逐，鄭靈之弒，不以褚師之不死而子公之不誅也，以未可以怒而有怒之色，未可誅而有誅之心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"怒其當罪，而誅不逆人心，雖懸奚害？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"夫未立有罪，即位之後，宿罪而誅，齊胡之所以滅也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"君行之臣，猶有後患，況為臣而行之君乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-9_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"誅既不當，而以盡為心，是與天下為讎也，則雖為戮，不亦可乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"衛靈公之時，彌子瑕有寵，於衛國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"侏儒有見公者曰：「臣之夢淺矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"」公曰：「奚夢？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"」「夢見竈者，為見公也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"」公怒曰：「吾聞見人主者夢見日，奚為見寡人而夢見竈乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"」侏儒曰：「夫日兼照天下，一物不能當也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"人君兼照一國，一人不能壅也，故將見人主而夢日也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"夫竈，一人煬焉，則後人無從見矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"或者一人煬君邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"則臣雖夢竈，不亦可乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"」公曰：「善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-10_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"」遂去雍鉏，退彌子瑕，而用司空狗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰：侏儒善假於夢以見主道矣，然靈公不知侏儒之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"去雍鉏，退彌子瑕，而用司空狗者，是去所愛而用所賢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"鄭子都賢慶建而壅焉，燕子噲賢子之而壅焉，夫去所愛而用所賢，未免使一人煬己也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"不肖者煬主不足以害明，今不加知而使賢者煬己，則必危矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"或曰屈到嗜芰，文王嗜菖蒲葅，非正味也，而二賢尚之，所味不必美。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"晉靈侯說參無恤，燕噲賢子之，非正士也，而二君尊之，所賢不必賢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"非賢而賢用之，與愛而用之同。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"賢誠賢而舉之，與用所愛異狀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"故楚莊舉叔孫而霸，商辛用費仲而滅，此皆用所賢而事相反也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"燕噲雖舉所賢而同於用所愛，衛奚距然哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"則侏儒之未可見也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"君壅而不知其壅也，已見之後而知其壅也，故退壅臣，是加知之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-21_p-12_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-21\",\n      \"passageId\": \"han-fei-zi_ch-21_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"日「不加知而使賢者煬己則必危」，而今以加知矣，則雖煬己必不危矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
